"""F4: the full check (src/full_check.py) once on the stance the overlay picked and once on TASK_CFG's, no retry (reads data/bench_stance_last.json written by bench_stance_validate.py).

    MUJOCO_GL=egl python experiments/f4_full_check.py
"""
import json
import math
import time

from src import bench_stance as bs
from src.full_check import FullCheck
from src.task_config import TASK_CFG
from src.task_points import task_points

if __name__ == "__main__":
    last = json.load(open("data/bench_stance_last.json"))
    maps = bs.load_maps("data/reach_map")
    fc = FullCheck(maps=maps)
    pts = task_points(fc.model, fc.scene_data)
    yaw = TASK_CFG["staging_yaw"]
    for name in ("task_cfg", "best"):
        st = last[name]
        stance = (st["xy"][0], st["xy"][1], yaw, st["q"])
        t0 = time.perf_counter()
        r = fc.check(stance, pts, use_cache=False)
        print(f"== {name}: stance {tuple(round(v, 3) for v in stance)}  ok={r['ok']}  failed={r['failed']}  {time.perf_counter() - t0:.1f} s")
        print("   reason:", r["reason"])
        for h in r["heights"]:
            print("   height", {k: (round(v, 3) if isinstance(v, float) else v) for k, v in h.items()})
        print("   ik:", [(e["stance"], e["ok"]) for e in r["ik"]])
    print("distance between the two stances (cm):", round(100 * math.hypot(last["best"]["xy"][0] - last["task_cfg"]["xy"][0], last["best"]["xy"][1] - last["task_cfg"]["xy"][1]), 1))
